  async function cacheCheck(){if(!('serviceWorker'in navigator))return{ok:false,label:'离线能力',detail:'浏览器不支持 Service Worker'};const registration=await navigator.serviceWorker.getRegistration();const cacheKeys='caches'in window?await caches.keys():[];return{ok:Boolean(registration),label:'离线能力',detail:registration?'Service Worker 已注册，缓存空间 '+cacheKeys.filter(key=>key.startsWith('travel-plans')).length+' 个':'尚未完成注册'}}
  function versionCheck(){const meta=document.querySelector('meta[name="travel-map-version"]')?.content,badge=document.querySelector('.eyebrow')?.textContent||'',deployment=document.getElementById('deploymentVersion')?.textContent||'',ok=meta==='2.5.0'&&badge.includes('v2.5.0')&&deployment.includes('v2.5.0');return{ok,label:'版本同步',detail:ok?'页面、徽标和部署标识一致':'检测到版本标识不同步'}}
