  function renderToday(){const box=document.getElementById('todayModeContent');if(!box)return;const today=chinaDate(),date=today.slice(5),day=schedule(date),enabled=document.getElementById('todayModeToggle')?.checked;if(!day){box.innerHTML='<p>今天是 '+escape(today)+'，尚未进入8月9日至16日旅行日期。</p><button type="button" id="openPlannedDay">打开当前选中日</button>';box.querySelector('#openPlannedDay').onclick=()=>syncMapDay(currentDay);return}const next=nextStop(day);box.innerHTML='<p><b>今天：8月'+Number(date.slice(3))+'日 · '+escape(day.title)+'</b></p><p>'+(next?'下一站：'+pointIcon(next.id)+' '+escape(shortName(next.name)):'当天站点已完成或跳过')+'</p><button type="button" id="openTodayRoute">'+(enabled?'打开当天路线':'临时打开当天路线')+'</button>';box.querySelector('#openTodayRoute').onclick=()=>{currentDay=day.date;syncMapDay(day.date);renderAll()}}
  function renderNextStop(){const box=document.getElementById('nextStopPanel'),day=schedule(currentDay);if(!box||!day)return;const entry=nextStopEntry(day);if(!entry){box.innerHTML='<div class="trip-tool-head"><b>下一站行动卡</b><span>当日完成</span></div><p class="next-stop-done">🎉 当天所有站点已完成或跳过。</p><button type="button" data-operation-undo>撤销上一步</button>';return}const p=entry.point,comparison=modeComparison?.pointId===p.id?modeComparison:null;box.innerHTML='<div class="trip-tool-head"><b>下一站行动卡</b><span>8月'+Number(day.date.slice(3))+'日 · 第'+(entry.index+1)+'站</span></div><div class="next-stop-main"><div class="next-stop-title">'+pointIcon(p.id)+' <b>'+escape(shortName(p.name))+'</b><small>'+escape(p.status||'')+'</small></div><p>'+escape(p.transport||'请按地图实时导航')+'</p><div class="next-stop-actions"><button type="button" data-next-action="focus">地图定位</button><button type="button" data-next-action="compare">比较步行/公交/打车</button><button type="button" data-next-action="complete" class="primary-action">完成本站</button><button type="button" data-next-action="skip">跳过</button><button type="button" data-operation-undo>撤销</button></div>'+(comparison?'<div class="mode-compare">'+['walking','transit','driving'].map(mode=>modeCard(mode,comparison.results[mode])).join('')+'</div>':'')+'</div>'}
  function routeMetrics(mode,result){if(!result?.ok)return null;const data=result.data,path=mode==='transit'?data?.route?.transits?.[0]:data?.route?.paths?.[0],distance=Number(path?.distance||data?.route?.distance||0),duration=Number(path?.duration||path?.cost?.duration||0);return{distance,duration,cost:Number(path?.cost||data?.route?.taxi_cost||0)}}
