  function openNextRoute(mode){const day=schedule(currentDay),entry=nextStopEntry(day);if(!entry)return;toggleAmapServicePanel(true);amapShowPane('route');amapRouteMode=mode;document.querySelectorAll('[data-amap-route-mode]').forEach(button=>button.classList.toggle('active',button.dataset.amapRouteMode===mode));const origin=amapCurrentLocation||amapPointPosition(pointById('hotel-zone')),destination=amapPointPosition(entry.point);amapSetInputLocation('amapRouteFrom',amapCurrentLocation?amapCurrentLabel:'住宿区',origin);amapSetInputLocation('amapRouteTo',entry.point.name,destination);TravelAmapAssistantController.planRoute()}
