  async function renderTrack(){const box=document.getElementById('trackPanel');if(!box)return;const track=await TravelTrackStore.get(currentDay);box.innerHTML='<div class="trip-tool-head"><b>GPX轨迹</b><span>补足景区内部步行</span></div>'+(track?'<p><b>'+escape(track.name)+'</b><br>'+track.points.length+' 个点 · '+(track.distance/1000).toFixed(2)+' km · '+escape(track.importedAt)+'</p><div class="tool-action-row"><button type="button" data-track-show>显示轨迹</button><button type="button" data-track-clear>删除轨迹</button></div>':'<p>可导入当天真实轨迹或提前规划的GPX。导入后体力风险优先使用该轨迹。</p>')+'<label class="gpx-import">选择GPX<input type="file" id="gpxFileInput" accept=".gpx,application/gpx+xml,application/xml,text/xml"></label><div id="gpxImportStatus"></div>';box.querySelector('#gpxFileInput').onchange=async event=>{const status=box.querySelector('#gpxImportStatus');status.textContent='正在解析轨迹…';try{const record=await TravelTrackStore.importFile(currentDay,event.target.files?.[0]);TravelRiskMetrics.clear(currentDay);lastRisk=null;status.textContent='已导入 '+record.points.length+' 个点，'+(record.distance/1000).toFixed(2)+' km';TravelOperationLog?.record('track-import',{day:currentDay,name:record.name},{kind:'track-remove',day:currentDay},'导入 '+record.name);await renderTrack();renderComfort(true)}catch(error){status.textContent='导入失败：'+error.message}}}
