  async function renderComfort(force=false){const box=document.getElementById('comfortContent'),day=schedule(currentDay);if(!box||!day)return;box.innerHTML='<p>正在核算可核验步行、轨迹、高程和逐小时体感……</p>';const result=await TravelRiskMetrics.get(day,{force});lastRisk=result;const value=comfort(day,result.data||{}),quality=result.data?.quality||{};box.innerHTML='<div class="risk-level risk-'+value.level+'">'+value.level+'风险</div><p>'+value.reasons.map(escape).join('；')+'</p><div class="quality-grid"><span>步行：'+escape(quality.walking||'--')+'</span><span>高程：'+escape(quality.elevation||'--')+'</span><span>天气：'+escape(quality.hourly||'--')+'</span></div><small>累计爬升可能来自GPX内嵌高程或90m DEM近似值，现场体感优先。 <a href="https://open-meteo.com/en/docs/elevation-api" target="_blank" rel="noopener">Open-Meteo</a> · <a href="https://dataspace.copernicus.eu/" target="_blank" rel="noopener">Copernicus DEM</a></small>';renderRain()}
