  function cardText(day){const bookings=bookingItemsForDay(day.date),entries=routeEntries(day);return['8月'+Number(day.date.slice(3))+'日｜'+day.title,'天气：'+weatherText(day.date),'路线：'+entries.map(entry=>(entry.index+1)+'. '+shortName(entry.point.name)+'（'+statusLabel(stopValue(day.date,entry.point.id,entry.occurrence))+'）').join(' → '),'摘要：'+day.summary,bookings.length?'预约：'+bookings.map(b=>b.name).join('；'):'预约：无','Plan B：'+day.planB].join('\n')}
