  function foodStatus(item){const map={must:'必吃/必买',wanted:'想吃备选'};return `${map[item.priority]||'已收录'} · ${dateLabel(item.suggestedDate)}`}
  function mapAction(item){if(item.pointId)return `<button type="button" data-wishlist-focus="${esc(item.pointId)}">地图定位</button>`;if(item.mapUrl)return `<a href="${esc(item.mapUrl)}" target="_blank" rel="noopener">高德核对</a>`;return''}
  function aliases(item){const list=[...(item.aliases||[])];if(item.original&&item.original!==item.name)list.unshift(item.original);return list.length?`<small>原话/别名：${list.map(esc).join('、')}</small>`:''}
  function itemHtml(item,type){const checked=done(item.id),status=type==='attraction'?attractionStatus(item):foodStatus(item);return `<article class="wishlist-item ${checked?'done':''}" data-wishlist-type="${type}" data-wishlist-id="${esc(item.id)}"><label class="wishlist-check"><input type="checkbox" data-wishlist-done="${esc(item.id)}" ${checked?'checked':''}><span aria-hidden="true"></span></label><div class="wishlist-main"><div class="wishlist-name"><b>${esc(item.name)}</b>${item.target?`<em>${esc(item.target)}</em>`:''}</div>${aliases(item)}<div class="wishlist-status">${esc(status)}${item.suggestedMoment?` · ${esc(item.suggestedMoment)}`:''}</div>${item.address?`<small>${esc(item.address)}</small>`:''}${item.note?`<p>${esc(item.note)}</p>`:''}</div><div class="wishlist-actions">${mapAction(item)}${item.sourceUrl?`<a href="${esc(item.sourceUrl)}" target="_blank" rel="noopener">来源</a>`:''}</div></article>`}
  function coverage(){const routeIds=new Set((SCHEDULES||[]).flatMap(day=>day.route||[])),scheduleText=(SCHEDULES||[]).map(day=>JSON.stringify(day)).join(' '),attractions=wishlistAttractions.map(item=>({id:item.id,covered:item.coverage==='conditional'?routeIds.has(item.pointId)||scheduleText.includes(item.name)||(item.aliases||[]).some(alias=>scheduleText.includes(alias)):routeIds.has(item.pointId)})),foods=data.food.map(item=>({id:item.id,tracked:true}));return{attractions,totalAttractions:attractions.length,coveredAttractions:attractions.filter(item=>item.covered).length,foods,totalFoods:foods.length,completed:Object.keys(read()).length}}
  function summaryHtml(){const state=coverage();return `<div class="wishlist-summary"><span><b>${state.coveredAttractions}/${state.totalAttractions}</b> 个独立景点已覆盖</span><span><b>${state.totalFoods}</b> 项餐饮/饮料/购买任务已收录</span><span><b>${state.completed}</b> 项已完成</span></div>`}
  function filtered(){const attractions=wishlistAttractions.map(item=>({item,type:'attraction'})),food=data.food.map(item=>({item,type:'food'}));return [...attractions,...food].filter(entry=>(filter==='all'||filter===entry.type)&&(!onlyPending||!done(entry.item.id)))}
  function panelHtml(){const entries=filtered();return `<div class="trip-tool-head wishlist-head"><div><b>${esc(data.title)}</b><span>用户原话完整保留，重复名称按同一地点处理</span></div><button type="button" data-wishlist-reset>重置完成状态</button></div>${summaryHtml()}<div class="wishlist-toolbar" role="group" aria-label="清单筛选"><button type="button" data-wishlist-filter="all" class="${filter==='all'?'active':''}">全部</button><button type="button" data-wishlist-filter="attraction" class="${filter==='attraction'?'active':''}">景点</button><button type="button" data-wishlist-filter="food" class="${filter==='food'?'active':''}">餐饮与购买</button><label><input type="checkbox" data-wishlist-pending ${onlyPending?'checked':''}> 只看未完成</label></div><div class="wishlist-list">${entries.map(entry=>itemHtml(entry.item,entry.type)).join('')||'<p class="wishlist-empty">当前筛选下已全部完成。</p>'}</div><div class="wishlist-seafood-rule"><b>${esc(data.seafoodRule.title)}</b><p>${esc(data.seafoodRule.text)}</p></div>`}
  function ensure(){if(panel&&panel.isConnected)return panel;const root=document.getElementById('tripToolsRoot');if(!root)return null;panel=document.createElement('section');panel.id='girlfriendWishlistPanel';panel.className='trip-tool-card wide girlfriend-wishlist-card';const anchor=root.querySelector('#nextStopPanel');if(anchor)anchor.insertAdjacentElement('afterend',panel);else root.prepend(panel);bind();return panel}
