/* v2.5 availability controls for rain alternatives and temporary closures. */
(function(){
  'use strict';
  let observer=null,decorating=false,bound=false;
  function point(id){return typeof pointById==='function'?pointById(id):null}
  function rank(status){return({open:0,limited:1,unknown:2,full:3,closed:4})[status]??2}
  function sourceLink(p,item){const url=item?.sourceUrl||p?.sourceUrl||p?.mapUrl||'';return url?`<a href="${escapeHtml(url)}" target="_blank" rel="noopener">核对来源</a>`:''}
  function view(id){const p=point(id),item=TravelAvailability.get(id,{allowExpired:true}),status=item&&!item.expired?item.status:'unknown',checked=item?.checkedAt?new Date(item.checkedAt).toLocaleString('zh-CN',{hour12:false}):'',expired=Boolean(item?.expired),signature=[status,expired?'expired':'current',item?.checkedAt||'',item?.note||'',item?.sourceUrl||p?.sourceUrl||p?.mapUrl||''].join('|');return{p,item,status,checked,expired,signature}}
  function control(id,state=view(id)){const{p,item,status,checked,expired,signature}=state;return `<div class="availability-row" data-availability-row="${id}" data-rank="${rank(status)}" data-signature="${escapeHtml(signature)}"><div><b>${escapeHtml(TravelAvailability.STATUSES[status])}</b><small>${expired?'上次确认已过期':checked?'确认于 '+escapeHtml(checked):'建议出发前从官方来源复核'}${item?.note?' · '+escapeHtml(item.note):''}</small></div><select data-availability-status="${id}" aria-label="${escapeHtml(p?.name||id)}开放状态">${Object.entries(TravelAvailability.STATUSES).map(([value,label])=>`<option value="${value}" ${value===status?'selected':''}>${label}</option>`).join('')}</select>${sourceLink(p,item)}</div>`}
  function decorate(){if(decorating)return;const list=document.querySelector('#rainAlternativeContent .rain-alternatives');if(!list)return;decorating=true;try{const buttons=[...list.querySelectorAll(':scope > button[data-focus-stop]')];for(const [index,button] of buttons.entries()){const id=button.dataset.focusStop,state=view(id),selector=`:scope > [data-availability-row="${CSS.escape(id)}"]`;let row=list.querySelector(selector);if(!row){button.insertAdjacentHTML('afterend',control(id,state));row=button.nextElementSibling}else if(row.dataset.signature!==state.signature){row.outerHTML=control(id,state);row=list.querySelector(selector)}const order=rank(state.status)*100+index*2;button.style.order=String(order);if(row)row.style.order=String(order+1);button.dataset.availability=state.status;button.setAttribute('aria-disabled',String(['closed','full'].includes(state.status)))}}finally{decorating=false}}
  function change(event){const select=event.target.closest('[data-availability-status]');if(!select)return;const id=select.dataset.availabilityStatus,p=point(id),status=select.value,note=status==='closed'?'临时关闭/停运，12小时后自动过期':status==='full'?'预约已满，12小时后自动过期':'出发前人工确认，12小时后自动过期';TravelAvailability.set(id,status,{note,sourceUrl:p?.sourceUrl||p?.mapUrl||''});TravelOperationLog?.record('availability',{id,status},null,(p?.name||id)+'：'+TravelAvailability.STATUSES[status]);decorate();document.dispatchEvent(new CustomEvent('travel:rain-ranking-change',{detail:{id,status}}))}
  function bind(){if(bound)return;const root=document.getElementById('rainAlternativePanel');if(!root)return;bound=true;root.addEventListener('change',change);observer=new MutationObserver(records=>{if(records.some(record=>record.addedNodes.length||record.removedNodes.length))decorate()});observer.observe(root,{childList:true,subtree:true});decorate()}
  const originalInit=window.TravelTripOperations?.init;if(originalInit&&!originalInit.__availability)window.TravelTripOperations.init=Object.assign(function(...args){const result=originalInit.apply(this,args);window.TravelTripOperations?.renderAll?.();bind();return result},{__availability:true});
  document.addEventListener('travel:availability-change',decorate);
  window.TravelAvailabilityController=Object.freeze({bind,decorate,change,view});
})();

/* v2.5 status-aware calendar export with stable UIDs and cancellation updates. */
(function(){
  'use strict';
  const START='2026-08-09';let panel,events=[];
  function shift(date,days){return new Date(Date.parse(`${date}T00:00:00Z`)+days*86400000).toISOString().slice(0,10)}
  function compact(date){return date.replaceAll('-','')}
  function escapeIcs(value){return String(value??'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
  function bookingOpen(item){const note=String(item.note||''),match=note.match(/(?:提前|参观前)\s*(\d+)\s*日(?:内)?/);if(!match||!item.dates?.length)return[];const days=Number(match[1]),progress=progressValue(item.id),done=['booked','checked'].includes(progress),abandoned=progress==='abandoned',status=abandoned?'CANCELLED':'CONFIRMED',sequence=progress==='pending'?0:1,title=abandoned?`取消预约提醒：${item.name}`:done?`预约已完成：${item.name}`:`检查预约开放：${item.name}`,stateText=abandoned?'已在网页中标记放弃；重新导入可取消原提醒。':done?`网页状态为${progress==='checked'?'已核验':'已预约/购票'}。`:`页面资料记录“${match[0]}”。这是预约开放检查日，不是保证有票的截止日。`;return item.dates.map(mmdd=>({id:`booking-${item.id}-${mmdd}`,date:shift(`2026-${mmdd}`,-days),title,description:`${stateText}${item.optional?'该项目属于备选行程。':''}`,category:'预约购票',sourceId:item.id,status,sequence}))}
  function preparationEvents(){return[
    {id:'hotel-review',date:shift(START,-14),title:'复核青岛酒店订单',description:'核对准确地址、入住联系人、早餐、安静房、免费取消和含税总价。',category:'住宿'},
    {id:'rent-review',date:shift(START,-14),title:'复核租衣妆造订单',description:'确认门店地址、到店时段、妆造时长、押金、归还和雨天取消规则。',category:'订单'},
    {id:'trip-7',date:shift(START,-7),title:'青岛旅行出发前7天检查',description:'逐项核对预约购票、实名信息、酒店地址和交通方案。',category:'出发准备'},
    {id:'trip-4',date:shift(START,-4),title:'青岛旅行出发前4天天气检查',description:'刷新天气、降雨和风力；根据提示准备雨天替代方案。',category:'出发准备'},
    {id:'trip-2',date:shift(START,-2),title:'青岛旅行出发前2天最终检查',description:'下载离线页面，保存订单截图，准备雨具、防晒、补水和常用药。',category:'出发准备'}].map(item=>({...item,status:'CONFIRMED',sequence:0}))}
  function itineraryEvents(){return SCHEDULES.map(day=>{const entries=window.TravelTripOperations?.routeEntries?.(day)||[],states=entries.map(entry=>TravelTripOperations.stopValue(day.date,entry.point.id,entry.occurrence)),allSkipped=states.length&&states.every(value=>value==='skipped'),completed=states.filter(value=>value==='completed').length,description=[day.summary,'路线：'+entries.map(entry=>shortName(entry.point.name)).join(' → '),'进度：'+completed+'/'+states.length+' 已完成','Plan B：'+day.planB].join('\n');return{id:'itinerary-'+day.date,date:'2026-'+day.date,title:'青岛行程｜'+day.title,description,category:'青岛逐日行程',status:allSkipped?'CANCELLED':'CONFIRMED',sequence:states.some(value=>value!=='pending')?1:0,allDay:true}})}
  function bookingEvents(){const items=[];for(const item of BOOKINGS||[])items.push(...bookingOpen(item));return items}
  function build({includeItinerary=false}={}){const all=[...preparationEvents(),...bookingEvents(),...(includeItinerary?itineraryEvents():[])],unique=new Map(all.map(item=>[item.id,item]));return[...unique.values()].sort((a,b)=>a.date.localeCompare(b.date)||a.title.localeCompare(b.title))}
  function eventIcs(item){const day=compact(item.date),uid=`${item.id}@travel-plans.local`,stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'),last=stamp,lines=['BEGIN:VEVENT',`UID:${escapeIcs(uid)}`,`DTSTAMP:${stamp}`,`LAST-MODIFIED:${last}`,`SEQUENCE:${Number(item.sequence)||0}`,`STATUS:${item.status||'CONFIRMED'}`];if(item.allDay){lines.push(`DTSTART;VALUE=DATE:${day}`,`DTEND;VALUE=DATE:${compact(shift(item.date,1))}`)}else lines.push(`DTSTART;TZID=Asia/Shanghai:${day}T090000`,`DTEND;TZID=Asia/Shanghai:${day}T093000`);lines.push(`SUMMARY:${escapeIcs(item.title)}`,`DESCRIPTION:${escapeIcs(item.description)}`,`CATEGORIES:${escapeIcs(item.category||'青岛旅行')}`);if(item.status!=='CANCELLED')lines.push('BEGIN:VALARM','TRIGGER:-PT10M','ACTION:DISPLAY',`DESCRIPTION:${escapeIcs(item.title)}`,'END:VALARM');lines.push('END:VEVENT');return lines.join('\r\n')}
  function calendarIcs(items,name='青岛旅行提醒',method='PUBLISH'){return['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Travel Plans//Qingdao 2026//ZH-CN','CALSCALE:GREGORIAN',`METHOD:${method}`,`X-WR-CALNAME:${escapeIcs(name)}`,...items.map(eventIcs),'END:VCALENDAR',''].join('\r\n')}
  function download(items,name,method='PUBLISH'){const blob=new Blob(['\ufeff',calendarIcs(items,name,method)],{type:'text/calendar;charset=utf-8'});if(window.TravelTripOperations?.downloadBlob)window.TravelTripOperations.downloadBlob(blob,`${name}.ics`);else{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${name}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
  function mount(){panel=document.getElementById('calendarExportPanel');if(!panel)return;events=build();const itinerary=itineraryEvents(),booking=bookingEvents(),cancelled=[...itinerary,...booking].filter(item=>item.status==='CANCELLED');panel.innerHTML=`<div class="trip-tool-head"><b>系统日历提醒</b><div><button type="button" id="exportAllCalendar">出发提醒</button><button type="button" id="exportBookingCalendar">预约状态更新</button><button type="button" id="exportItineraryCalendar">逐日行程更新</button>${cancelled.length?'<button type="button" id="exportCancelledCalendar">取消已放弃项目</button>':''}</div></div><p>网页下载标准 .ics 文件，打开后由系统日历确认导入。预约和逐日行程使用稳定UID；再次导入可更新“未处理、已完成、放弃”以及逐日完成状态。</p><div class="calendar-event-list">${events.map((item,index)=>`<div class="calendar-event-row ${item.status==='CANCELLED'?'cancelled':''}"><div><b>${item.date} · ${item.title}</b><small>${item.description}</small></div><button type="button" data-calendar-index="${index}">单独设置</button></div>`).join('')}</div>`;panel.querySelector('#exportAllCalendar').onclick=()=>download(events,'青岛旅行提醒-全部');panel.querySelector('#exportBookingCalendar').onclick=()=>download(booking,'青岛预约状态-当前');panel.querySelector('#exportItineraryCalendar').onclick=()=>download(itinerary,'青岛逐日行程-当前状态');panel.querySelector('#exportCancelledCalendar')?.addEventListener('click',()=>download(cancelled,'青岛旅行-取消更新','CANCEL'));panel.addEventListener('click',event=>{const button=event.target.closest('[data-calendar-index]');if(!button)return;const item=events[Number(button.dataset.calendarIndex)];if(item)download([item],`青岛旅行提醒-${item.title.replace(/[\\/:*?"<>|]/g,'-')}`,item.status==='CANCELLED'?'CANCEL':'PUBLISH')})}
  const previousAfterBootstrap=window.TravelV2?.afterBootstrap;if(window.TravelV2)window.TravelV2.afterBootstrap=function(){previousAfterBootstrap?.();mount()};
  document.addEventListener('travel:operation',()=>{if(panel)mount()});
  document.addEventListener('travel:booking-progress',()=>{if(panel)mount()});
  window.TravelCalendarExport={build,bookingEvents,itineraryEvents,calendarIcs,download,mount};
})();

/* v2.5 local data inventory, export/import and reset controls. */
(function(){
  'use strict';
  let panel;
  const storage=window.TravelVersionedStorage;
  const groups={
    booking:{label:'预约进度',keys:['qingdao-v107-booking-progress']},
    weather:{label:'天气快照',prefixes:['travel-plans-weather']},
    reminders:{label:'出发提醒状态',keys:['travel-plans-reminders-v2.2']},
    preferences:{label:'界面与功能偏好',prefixes:['travel-plans-v2:']},
    map:{label:'底图与抽屉状态',keys:['qingdao-v107-basemap'],prefixes:['travel-plans-v2:basemap','travel-plans-v2:explicit-basemap','travel-plans-v2:route-drawer-state']},
    progress:{label:'站点、交通段与操作记录',keys:['trip-stop-status-v2.5','trip-segment-overrides-v2.5','trip-operation-log-v2.5','trip-risk-metrics-v2.5']},
    finance:{label:'预算与实际支出',keys:['trip-finance-v2.5','trip-taxi-budget-v2.3']}
  };
  function matching(group){return storage?.keys({exact:group.keys||[],prefixes:group.prefixes||[]})||[]}
  function bytes(keys){return keys.reduce((sum,key)=>sum+(localStorage.getItem(key)?.length||0),0)}
  function schemaInfo(keys){const versions=new Set();for(const key of keys){try{const value=JSON.parse(localStorage.getItem(key));if(storage?.isEnvelope(value))versions.add('v'+value.schemaVersion);else versions.add('legacy')}catch{versions.add('invalid')}}return[...versions].join(' / ')||'--'}
  async function cacheInfo(){if(!('caches'in window))return{keys:[],bytes:null};const keys=await caches.keys();return{keys:keys.filter(key=>key.startsWith('travel-plans')),bytes:null}}
  async function trackInfo(){try{const tracks=await TravelTrackStore.list();return{count:tracks.length,points:tracks.reduce((sum,item)=>sum+(item.points?.length||0),0)}}catch{return{count:0,points:0}}}
  async function render(){panel=document.getElementById('localDataPanel');if(!panel)return;const cache=await cacheInfo(),tracks=await trackInfo();panel.innerHTML=`<div class="trip-tool-head"><b>本机数据管理</b><span>数据不会上传</span></div><div class="local-data-list">${Object.entries(groups).map(([id,group])=>{const keys=matching(group);return`<div class="local-data-row"><div><b>${group.label}</b><small>${keys.length}项 · 约${bytes(keys)}字符 · ${schemaInfo(keys)}</small></div><button type="button" data-clear-local="${id}" ${keys.length?'':'disabled'}>清除</button></div>`}).join('')}<div class="local-data-row"><div><b>GPX轨迹</b><small>${tracks.count}天 · ${tracks.points}个轨迹点 · IndexedDB优先</small></div><button type="button" data-clear-local="tracks" ${tracks.count?'':'disabled'}>删除</button></div><div class="local-data-row"><div><b>离线缓存</b><small>${cache.keys.length}个缓存空间</small></div><button type="button" data-clear-local="cache" ${cache.keys.length?'':'disabled'}>删除</button></div></div><div class="local-transfer-actions"><button type="button" id="exportLocalData">导出本机状态</button><label>导入状态文件<input type="file" id="importLocalData" accept="application/json,.json"></label></div><div id="localTransferStatus"></div><button type="button" class="danger-local-reset" id="resetAllLocalData">全部恢复默认</button><p class="section-note">导出文件包含当前浏览器中的旅行状态和GPX轨迹，方便两台设备之间手动同步。导入前会验证格式；不会覆盖仓库或固定历史版本。</p>`;panel.querySelectorAll('[data-clear-local]').forEach(button=>button.onclick=()=>clearGroup(button.dataset.clearLocal));panel.querySelector('#resetAllLocalData').onclick=resetAll;panel.querySelector('#exportLocalData').onclick=exportAll;panel.querySelector('#importLocalData').onchange=event=>importAll(event.target.files?.[0])}
  function clearKeys(keys){for(const key of keys)localStorage.removeItem(key)}
  async function clearGroup(id){
    if(id==='cache'){if(!confirm('删除当前浏览器保存的离线页面缓存？'))return;for(const key of (await cacheInfo()).keys)await caches.delete(key);await render();return}
    if(id==='tracks'){if(!confirm('删除当前浏览器保存的全部GPX轨迹？'))return;await TravelTrackStore.clear();TravelRiskMetrics?.clear?.();await render();TravelTripOperations?.renderAll?.();return}
    const group=groups[id];if(!group||!confirm(`清除“${group.label}”？`))return;clearKeys(matching(group));
    if(id==='booking'){try{bookingProgress={};refreshLinkedViews()}catch{}}
    if(id==='weather'){try{amapTripWeatherByDate={};amapTripWeatherReportTime='';renderDays();renderLegend()}catch{}}
    if(id==='reminders')window.TravelReminders?.refresh?.();
    if(id==='map'){try{window.TravelRouteDrawer?.setState?.('collapsed')}catch{}}
    if(['progress','finance','preferences'].includes(id))window.TravelTripOperations?.renderAll?.();
    await render()
  }
  async function exportAll(){const status=panel.querySelector('#localTransferStatus');status.textContent='正在整理本机数据…';try{const payload=storage.exportEntries(),tracks=await TravelTrackStore.list();payload.tracks=tracks;payload.appVersion=APP_VERSION;payload.note='仅包含本机旅行状态，不包含任何账户或云端数据';TravelTripOperations.downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),'青岛旅行计划-本机状态-'+new Date().toISOString().slice(0,10)+'.json');status.textContent='已导出 '+Object.keys(payload.entries).length+' 项本机数据和 '+tracks.length+' 天轨迹'}catch(error){status.textContent='导出失败：'+error.message}}
  async function importAll(file){const status=panel.querySelector('#localTransferStatus');if(!file)return;status.textContent='正在验证导入文件…';try{const payload=storage.validateImport(JSON.parse(await file.text()));if(!confirm('导入将合并同名状态；导入后页面会重新加载。继续吗？')){status.textContent='已取消导入';return}const written=storage.importEntries(payload);for(const track of payload.tracks||[])if(track?.day&&track?.points?.length>=2)await TravelTrackStore.save(track.day,track.points,track);status.textContent='已导入 '+written.length+' 项状态和 '+(payload.tracks?.length||0)+' 天轨迹，正在重新加载…';setTimeout(()=>location.reload(),450)}catch(error){status.textContent='导入失败：'+error.message}}
  async function resetAll(){if(!confirm('将预约进度、天气快照、提醒、偏好、站点状态、交通校正、轨迹、费用和离线缓存全部恢复默认？'))return;const keep=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(key)keep.push(key)}for(const key of keep)if(key.startsWith('travel-plans')||key.startsWith('qingdao-v107')||key.startsWith('trip-'))localStorage.removeItem(key);await TravelTrackStore.clear();if('caches'in window)for(const key of await caches.keys())if(key.startsWith('travel-plans'))await caches.delete(key);location.reload()}
  const previousAfterBootstrap=window.TravelV2?.afterBootstrap;if(window.TravelV2)window.TravelV2.afterBootstrap=function(){previousAfterBootstrap?.();render()};
  window.TravelLocalData={render,matching,clearGroup,resetAll,exportAll,importAll};
})();
